export function changeSpecies(pokemon,speciesId){if(pokemon.speciesId!==Number(speciesId)&&pokemon.variantId)pokemon.variantId='';pokemon.speciesId=Number(speciesId);}
export function retirePokemon(state,id,reason){const index=state.pokemon.findIndex(p=>p.id===id);if(index<0)return;const [p]=state.pokemon.splice(index,1);p.team=false;p.retired={reason,date:Date.now()};(state.retiredPokemon ||= []).push(p);if(state.selected===id)state.selected=state.pokemon[0]?.id||null;return p;}
export function restorePokemon(state,id){const index=(state.retiredPokemon||[]).findIndex(p=>p.id===id);if(index<0)return;const [p]=state.retiredPokemon.splice(index,1);let itemUnavailable=false;if(p.held){const qty=state.inventory.find(i=>i.id===p.held)?.qty||0,used=state.pokemon.filter(other=>other.held===p.held).length;if(used>=qty){p.held='';itemUnavailable=true;}}delete p.retired;p.team=false;state.pokemon.push(p);state.selected=p.id;return {pokemon:p,itemUnavailable};}
